const STOP=new Set(["في","على","من","حول","الى","و","ال"]);
const normQ=(s:string)=>s.replace(/[ً-ْٰـ]/g,"").replace(/[أإآٱ]/g,"ا").replace(/ى/g,"ي").replace(/ة/g,"ه").replace(/[‏‎_/().-·,]+/g," ").replace(/s+/g," ").trim();
export function manarForTitle(title: string): ManarFile[] {
  const q=normQ(title).split(" ").map((t)=>t.replace(/^ال/,"")).filter((t)=>t.length>3&&!STOP.has(t));
  return MANAR_FILES.map((m)=>{
    const mt=TOKS[m.file] ?? [];
    const shared=q.filter((t)=>mt.some((x)=>x===t||x.includes(t)||t.includes(x))).length;
    return { m, shared };
  }).filter((x)=>x.shared>=2).sort((a,b)=>b.shared-a.shared).slice(0,3).map((x)=>x.m);
}
